def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the separate, non-background tile components.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            comps.append((min(rs), min(cs), max(rs), max(cs)))

    # The common component size identifies complete tiles; edge-clipped tiles
    # are ignored.
    sizes = {}
    for t, l, b, r in comps:
        sizes[(b - t + 1, r - l + 1)] = sizes.get((b - t + 1, r - l + 1), 0) + 1
    if not sizes:
        return out
    th, tw = max(sizes, key=sizes.get)
    tiles = [(t, l, b, r) for t, l, b, r in comps
             if b - t + 1 == th and r - l + 1 == tw and th >= 3 and tw >= 3]

    # Read the color of each tile's interior and find the ordinary (most
    # frequent) interior color.
    entries = []
    counts = {}
    for t, l, b, r in tiles:
        vals = [grid[y][x] for y in range(t + 1, b)
                for x in range(l + 1, r)]
        if not vals:
            continue
        color = max(set(vals), key=vals.count)
        entries.append((t, l, b, r, color))
        counts[color] = counts.get(color, 0) + 1
    if not counts:
        return out
    ordinary = max(counts, key=counts.get)

    # Connect repeated non-ordinary interior colors through the blank gutters,
    # without changing the intervening tiles.
    for color in counts:
        if color == ordinary:
            continue
        relevant = [e for e in entries if e[4] == color]

        rows = {}
        for e in relevant:
            rows.setdefault(e[0], []).append(e)
        for group in rows.values():
            group.sort(key=lambda e: e[1])
            for a, b in zip(group, group[1:]):
                for y in range(a[0] + 1, a[2]):
                    for x in range(a[3] + 1, b[1]):
                        if grid[y][x] == 0:
                            out[y][x] = color

        cols = {}
        for e in relevant:
            cols.setdefault(e[1], []).append(e)
        for group in cols.values():
            group.sort(key=lambda e: e[0])
            for a, b in zip(group, group[1:]):
                for y in range(a[2] + 1, b[0]):
                    for x in range(a[1] + 1, a[3]):
                        if grid[y][x] == 0:
                            out[y][x] = color

    return out
